\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric, arrows.meta, positioning}
\pagestyle{empty}

% ── Custom Color Theme: Deep Navy + Warm Accents ──
\definecolor{primary}{HTML}{1a2332}     % deep navy
\definecolor{secondary}{HTML}{e07a5f}   % coral
\definecolor{accent}{HTML}{f6ad55}      % amber
\definecolor{teal}{HTML}{4fd1c5}        % teal
\definecolor{bgposter}{HTML}{f0f4f8}    % cool light gray-blue
\definecolor{redbg}{HTML}{fdf2f0}       % warm coral tint
\definecolor{bluebg}{HTML}{f0f7ff}      % cool blue tint
\definecolor{darkbg}{HTML}{f5f0eb}      % warm cream tint
\definecolor{redtitlebg}{HTML}{fce8e3}
\definecolor{bluetitlebg}{HTML}{e4f0ff}
\definecolor{darktitlebg}{HTML}{f0e8e0}
\definecolor{textdark}{HTML}{1a202c}
\definecolor{textgray}{HTML}{4a5568}
\definecolor{stathighlight}{HTML}{fff5f0}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!12!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
  herocard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!10!white,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=secondary!20!white,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=2mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{68}{82}\selectfont\bfseries The State of Global Education}\\[10pt]
  {\fontsize{38}{46}\selectfont\color{accent} Progress, Gaps, and Inequality}\\[10pt]
  {\fontsize{26}{32}\selectfont\color{white!70}
   Humanity reversed education from elite privilege to near-universal right --- yet 244 million children remain left behind.}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} < 1 $\to$ > 4}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} in 5 adults educated}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray} 1800 $\to$ Today}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{secondary} 244M}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} children out of school}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray} Globally, 2023}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} < 3 vs 10+}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} years quality schooling}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray} Poorest vs Richest}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══ LEFT COLUMN ══

% Card 1: Historical Progress
\posterbox[redcard, title={Two Centuries of Expansion}
]{name=historical, column=1, between=row5 and row10}{
  \fontsize{26}{34}\selectfont
  \posterfig{0.96}{figures/historical_progress}{}
  \vspace{2mm}
  \begin{itemize}[itemsep=6pt]
    \item 1800: education reserved for a small elite
    \item Today: majority literate, enrollment near-universal
  \end{itemize}
  \vspace{2mm}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\bfseries\color{textdark}
    A dramatic reversal in just 200 years\vspace{2pt}%
  }}
}

% Card 2: Learning Crisis
\posterbox[bluecard, title={The Learning Crisis}
]{name=crisis, column=1, between=row10 and row14}{
  \fontsize{26}{34}\selectfont
  \posterfig{0.96}{figures/learning_crisis}{}
  \vspace{2mm}
  \begin{itemize}[itemsep=6pt]
    \item Enrollment $\neq$ learning
    \item <20\% achieve minimum reading in low-income countries
    \item Hidden crisis behind attendance numbers
  \end{itemize}
}

% Card 3: Gender Gap
\posterbox[darkcard, title={Closing the Gender Gap}
]{name=gender, column=1, between=row14 and row18}{
  \fontsize{26}{34}\selectfont
  \posterfig{0.96}{figures/gender_gap}{}
