    \centering\fontsize{22}{28}\selectfont\bfseries\color{textdark}
    Despite progress, 1 in 10 school-age children never enter a classroom\vspace{2pt}%
  }}
}

% Card 6: Quality Gap
\posterbox[bluecard, title={A World Divided: Quality Schooling}
]{name=quality, column=2, between=row11 and row16}{
  \fontsize{26}{34}\selectfont
  \posterfig{0.96}{figures/quality_gap}{}
  \vspace{2mm}
