    \item Poorest countries: <3 years learning-adjusted
    \item High-income countries: 10+ years
    \item South Asia \& Sub-Saharan Africa: <7 years average
  \end{itemize}
  \vspace{2mm}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\bfseries\color{textdark}
    Children in poorest nations receive < $\frac{1}{3}$ the schooling of wealthy peers\vspace{2pt}%
  }}
}

% Card 7: Footer / Sources
\posterbox[darkcard, title={About This Exhibition}
]{name=footer, column=2, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont
  \centering
  \vspace{2mm}
  {\fontsize{22}{28}\selectfont\color{textgray}
   Data: UNESCO Institute for Statistics, World Bank, \&\n global education research (2020--2023).}\\[6pt]
  {\fontsize{20}{26}\selectfont\color{textgray}
   Designed for public exhibition. Sources available upon request.}
  \vspace{2mm}
}

\end{tcbposter}
\end{document}
